const CSS = ".ol-ta { --ta-speed: 1; --ta-dur: 700ms; --ta-step: 40ms; }\n.ol-ta .ol-oc { backface-visibility: hidden; }\n.ol-ta.is-playing .ol-oc {\n  animation-duration: calc(var(--ta-dur) / var(--ta-speed));\n  animation-delay: calc(var(--i, 0) * var(--ta-step) / var(--ta-speed));\n  animation-fill-mode: both;\n  animation-timing-function: cubic-bezier(.2, .8, .2, 1);\n}\n.ol-ta[data-anim=\"rise\"] { --ta-dur: 760ms; --ta-step: 45ms; }\n.ol-ta[data-anim=\"rise\"].is-playing .ol-oc { animation-name: ol-ta-rise; }\n.ol-ta[data-anim=\"wave\"] { --ta-dur: 720ms; --ta-step: 55ms; }\n.ol-ta[data-anim=\"wave\"].is-playing .ol-oc { animation-name: ol-ta-wave; animation-timing-function: ease-in-out; animation-fill-mode: none; }\n.ol-ta[data-anim=\"type\"] { --ta-step: 85ms; }\n.ol-ta[data-anim=\"type\"].is-playing .ol-oc { animation-name: ol-ta-type; animation-duration: 1ms; animation-timing-function: steps(1); }\n.ol-ta-cursor { position: absolute; z-index: 2; width: .075em; border-radius: .02em; background: var(--scene-accent, currentColor); pointer-events: none; }\n.ol-ta-cursor.is-done { animation: ol-ta-caret-blink .9s steps(1) infinite; }\n.ol-ta .ol-hl-accent.ol-ta-swap-out { transform: translateY(-.35em); opacity: 0; transition: transform .2s ease-in, opacity .2s ease-in; }\n.ol-ta .ol-hl-accent.ol-ta-swap-in { animation: ol-ta-swap-in .28s cubic-bezier(.16, 1, .3, 1) both; }\n.ol-ta .ol-oc.ol-ta-tick { animation: ol-ta-tick 90ms linear; }\n.ol-ta-draw { position: absolute; left: -14%; top: -16%; width: 128%; height: 132%; overflow: visible; pointer-events: none; }\n.ol-ta-draw path { fill: none; stroke: var(--scene-accent, currentColor); stroke-width: 3px; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }\n.ol-ta .ol-oc.ol-ta-flap { transform-origin: 50% 0; animation: ol-ta-flap 150ms ease-out; }\n.ol-ta .ol-hl-accent.ol-ta-typing::after {\n  content: \"\";\n  display: inline-block;\n  width: .07em;\n  height: .72em;\n  margin-left: .05em;\n  background: var(--scene-accent, currentColor);\n  vertical-align: baseline;\n  animation: ol-ta-caret-blink .8s steps(1) infinite;\n}\n.ol-ta-draw.is-under { top: 80%; height: 34%; left: -3%; width: 106%; }\n@keyframes ol-ta-rise { from { opacity: 0; transform: translateY(.55em); } }\n@keyframes ol-ta-wave { 0%, 100% { transform: none; } 40% { transform: translateY(-.3em); } 70% { transform: translateY(.05em); } }\n@keyframes ol-ta-type  { from { opacity: 0; } to { opacity: 1; } }\n@keyframes ol-ta-caret-blink { 50% { opacity: 0; } }\n@keyframes ol-ta-swap-in { from { transform: translateY(.4em); opacity: 0; } }\n@keyframes ol-ta-tick { from { transform: translateY(-.22em); filter: blur(1.5px); opacity: .6; } }\n@keyframes ol-ta-flap { from { transform: rotateX(-85deg); filter: brightness(.65); } }"

const CHARSETS: Record<string, string> = {
    mixed: "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#%&*+=?",
    letters: "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
    numbers: "0123456789",
    binary: "01",
    symbols: "#%&*+=?!/<>[]{}$@",
}

/* ---------- text -> lines, words, letters (same classes and variables the modui motion expects) ---------- */

function steady(i: number) { const x = Math.sin(i * 12.9898 + 78.233) * 43758.5453; return x - Math.floor(x) }

// the place of a unit (letter, word or line) in the play order: --i
function order(u: number, count: number, direction: string) {
    const mid = (count - 1) / 2
    if (direction === "rtl") return count - 1 - u
    if (direction === "center") return Math.abs(u - mid)
    if (direction === "edges") return mid - Math.abs(u - mid)
    if (direction === "random") return Math.floor(steady(u + 7) * count)
    return u
}

// where the accent goes: the accent word if it is in the text, otherwise the whole text (mark) or the last word (accent)
function locate(lines: string[], accent: string, wrap: string) {
    if (!wrap) return []
    const want = accent.trim()
    if (want) {
        for (let li = 0; li < lines.length; li++) {
            let a = lines[li].indexOf(want)
            if (a < 0) a = lines[li].toLowerCase().indexOf(want.toLowerCase())
            if (a >= 0) return [{ li, a, b: a + want.length }]
        }
    }
    if (wrap === "mark") return lines.map((l, li) => ({ li, a: 0, b: l.length })).filter((r) => r.b > 0)
    if (wrap === "strike") {
        for (let li = 0; li < lines.length; li++) {
            const m = lines[li].match(/\S+/)
            if (m) return [{ li, a: m.index, b: m.index + m[0].length }]
        }
        return []
    }
    for (let li = lines.length - 1; li >= 0; li--) {
        const m = lines[li].match(/\S+\s*$/)
        if (m) return [{ li, a: m.index, b: m.index + m[0].trimEnd().length }]
    }
    return []
}

function build(text: string, accent: string, wrap: string, split: string, direction: string) {
    const lines = String(text || "").split("\n")
    const spans = locate(lines, accent, wrap)

    // first count letters and words, so the order can run from either end
    let n = 0, w = 0
    const data = lines.map((line, li) => {
        const hit = spans.find((s) => s.li === li)
        const parts = hit
            ? [{ part: line.slice(0, hit.a), marked: false }, { part: line.slice(hit.a, hit.b), marked: true }, { part: line.slice(hit.b), marked: false }]
            : [{ part: line, marked: false }]
        let k = 0
        const segs = parts.map(({ part, marked }) => ({
            marked,
            tokens: part.split(/(\s+)/).filter(Boolean).map((tok) => /^\s+$/.test(tok)
                ? { space: true, w: 0, chars: [] }
                : { space: false, w: w++, chars: Array.from(tok).map((ch) => ({ ch, n: n++, k: k++ })) }),
        }))
        return { line, segs, own: k }
    })
    const N = n, W = w, L = lines.length

    return data.map(({ line, segs, own }, li) => {
        const mid = (own - 1) / 2
        const render = (tokens, key: string) => tokens.map((t, ti) => t.space ? " " : (
            <span key={key + ti} className="ol-w">
                {t.chars.map(({ ch, n, k }) => {
                    const unit = split === "word" ? t.w : split === "line" ? li : n
                    const count = split === "word" ? W : split === "line" ? L : N
                    const cls = "ol-oc" + (n % 2 ? " ol-ta-odd" : "") + (n === N - 1 ? " ol-ta-last" : "") + (/\d/.test(ch) ? " ol-ta-digit" : "")
                    const vars: any = {
                        "--i": order(unit, count, direction), "--r": steady(n).toFixed(3), "--k": k, "--li": li, "--oli": li,
                        "--s": (k - mid).toFixed(1), "--c": Math.abs(k - mid).toFixed(1),
                    }
                    return <span key={n} className={cls} style={vars}>{ch}</span>
                })}
            </span>
        ))
        const body = segs.map((s, si) => !s.marked
            ? <React.Fragment key={si}>{render(s.tokens, si + "-")}</React.Fragment>
            : wrap === "mark" || wrap === "strike"
                ? <span key={si} className={wrap === "mark" ? "ol-hl-mark" : "ol-strike"}>{render(s.tokens, si + "-")}</span>
                : <span key={si} className="ol-hl-accent"><span>{render(s.tokens, si + "-")}</span></span>)
        return (
            <span key={li} className={"ol-hl-line" + (li === 0 ? " ol-ta-first" : "")} style={{ "--li": li } as any}>
                {line ? body : " "}
            </span>
        )
    })
}

/* ---------- motions that need JavaScript (ported from the modui engine) ---------- */

type Job = { end: () => void; done: Promise<void> }

const lettersOf = (root: HTMLElement) => Array.from(root.querySelectorAll(".ol-oc")) as HTMLElement[]
const digitsOf = (root: HTMLElement) => lettersOf(root).filter((o) => /^\d$/.test(o.textContent || ""))
function signal() { let resolve: () => void = () => {}; const done = new Promise<void>((r) => { resolve = r }); return { done, resolve } }
function retrigger(o: HTMLElement, cls: string) { o.classList.remove(cls); void o.offsetWidth; o.classList.add(cls) }

// scramble: random characters in every slot lock into the real letters, in the play order (--i)
function scramble(root: HTMLElement, speed: number, p: any): Job | null {
    const all = lettersOf(root)
    if (!all.length) return null
    const finals = all.map((o) => o.textContent || "")
    const pool = (p.charset === "custom" ? p.chars : CHARSETS[p.charset]) || CHARSETS.mixed
    const at = all.map((o) => (300 + (parseFloat(o.style.getPropertyValue("--i")) || 0) * 45) / speed)
    const { done, resolve } = signal()
    let frame = 0
    // a random letter takes the case of the real one, so each slot keeps roughly its own width
    const random = (i: number) => {
        const c = pool[Math.floor(Math.random() * pool.length)], f = finals[i]
        if (f !== f.toUpperCase()) return c.toLowerCase()
        if (f !== f.toLowerCase()) return c.toUpperCase()
        return c
    }
    const spin = (o: HTMLElement, i: number) => { o.textContent = random(i); o.style.color = p.accentColor }
    const settle = (o: HTMLElement, i: number) => { o.textContent = finals[i]; o.style.color = ""; o.style.width = ""; o.style.textAlign = "" }
    const end = () => { cancelAnimationFrame(frame); all.forEach(settle); resolve() }
    all.forEach((o) => { o.style.width = o.offsetWidth + "px"; o.style.textAlign = "center" })
    all.forEach(spin)
    const start = performance.now()
    const tick = (now: number) => {
        const t = now - start
        let left = false
        all.forEach((o, i) => {
            // check the colour too: a random letter can land on the real one and keep the scramble colour
            if (t >= at[i]) { if (o.textContent !== finals[i] || o.style.color) settle(o, i) }
            else { left = true; if (Math.random() < 0.45) spin(o, i) }
        })
        if (left) frame = requestAnimationFrame(tick); else end()
    }
    frame = requestAnimationFrame(tick)
    return { end, done }
}

// odometer: every slot always shows a digit, zeros in front of the number are dimmed
function counter(root: HTMLElement, speed: number): Job | null {
    const digits = digitsOf(root)
    if (!digits.length) return null
    const finals = digits.map((o) => o.textContent), target = +finals.join("")
    const duration = 1600 / speed, start = performance.now(), { done, resolve } = signal()
    let frame = 0
    const show = (v: number) => {
        const raw = String(Math.round(v)), lead = digits.length - raw.length, s = raw.padStart(digits.length, "0")
        digits.forEach((o, i) => { o.textContent = s[i]; o.style.opacity = i < lead ? ".22" : "" })
    }
    const end = () => { cancelAnimationFrame(frame); digits.forEach((o, i) => { o.textContent = finals[i]; o.style.opacity = "" }); resolve() }
    const tick = (now: number) => {
        const p = Math.max(0, Math.min(1, (now - start) / duration))
        show(target * (1 - Math.pow(1 - p, 3)))
        if (p < 1) frame = requestAnimationFrame(tick); else end()
    }
    show(0)
    frame = requestAnimationFrame(tick)
    return { end, done }
}

// slot machine: every digit spins, left ones stop first
function slot(root: HTMLElement, speed: number): Job | null {
    const digits = digitsOf(root)
    if (!digits.length) return null
    const finals = digits.map((o) => o.textContent), { done, resolve } = signal()
    let count = 0, timer = 0
    const end = () => { clearTimeout(timer); digits.forEach((o, i) => { o.textContent = finals[i]; o.classList.remove("ol-ta-tick") }); resolve() }
    const tick = () => {
        count++
        let spinning = false
        digits.forEach((o, i) => {
            if (count > 10 + i * 7) { o.textContent = finals[i]; return }
            spinning = true
            o.textContent = String(Math.floor(Math.random() * 10))
            retrigger(o, "ol-ta-tick")
        })
        if (spinning) timer = window.setTimeout(tick, 70 / speed); else end()
    }
    timer = window.setTimeout(tick, 150 / speed)
    return { end, done }
}

// flip clock: counts up, every digit that changes folds down
function flipclock(root: HTMLElement, speed: number): Job | null {
    const digits = digitsOf(root)
    if (!digits.length) return null
    const finals = digits.map((o) => o.textContent), target = +finals.join("")
    const duration = 1600 / speed, start = performance.now(), { done, resolve } = signal()
    let timer = 0
    const show = (v: number) => {
        const s = String(Math.round(v)).padStart(digits.length, "0")
        digits.forEach((o, i) => { if (o.textContent !== s[i]) { o.textContent = s[i]; retrigger(o, "ol-ta-flap") } })
    }
    const end = () => { clearTimeout(timer); digits.forEach((o, i) => { o.textContent = finals[i]; o.classList.remove("ol-ta-flap") }); resolve() }
    const tick = () => {
        const p = Math.max(0, Math.min(1, (performance.now() - start) / duration))
        show(target * (1 - Math.pow(1 - p, 3)))
        if (p < 1) timer = window.setTimeout(tick, 80 / speed); else end()
    }
    show(0)
    timer = window.setTimeout(tick, 80 / speed)
    return { end, done }
}

// typewriter: letters appear by CSS, one caret follows the newest letter, then blinks at the end
function typing(root: HTMLElement, speed: number): Job | null {
    const all = lettersOf(root)
    if (!all.length) return null
    const step = parseFloat(getComputedStyle(root).getPropertyValue("--ta-step")) || 70
    const cursor = document.createElement("span")
    cursor.className = "ol-ta-cursor"
    cursor.setAttribute("aria-hidden", "true")
    root.appendChild(cursor)
    const start = performance.now(), { done, resolve } = signal()
    let frame = 0
    const place = (i: number) => {
        const r = all[i].getBoundingClientRect(), box = root.getBoundingClientRect()
        const scale = root.offsetWidth ? box.width / root.offsetWidth : 1
        cursor.style.left = (r.right - box.left) / scale + "px"
        cursor.style.top = (r.top - box.top) / scale + "px"
        cursor.style.height = r.height / scale + "px"
    }
    const tick = (now: number) => {
        const i = Math.min(all.length - 1, Math.floor(Math.max(0, now - start) / (step / speed)))
        place(i)
        if (i < all.length - 1) frame = requestAnimationFrame(tick)
        else { cursor.classList.add("is-done"); resolve() }
    }
    place(0)
    frame = requestAnimationFrame(tick)
    return { end: () => { cancelAnimationFrame(frame); cursor.remove(); resolve() }, done }
}

// word rotator: the accent word swaps through the list ([{ word, color }]), then comes back
function rotator(root: HTMLElement, speed: number, p: any): Job | null {
    const target = root.querySelector(".ol-hl-accent") as HTMLElement | null
    const words = (Array.isArray(p.words) ? p.words : []).filter((w) => w && String(w.word || "").trim())
    if (!target || !words.length) return null
    const own = target.firstElementChild as HTMLElement
    const alt = document.createElement("span")
    const { done, resolve } = signal()
    let step = 0, timer = 0
    const show = (w: any) => {
        if (w === null) { alt.remove(); own.style.display = ""; return }
        alt.textContent = String(w.word).trim()
        alt.style.color = w.color || ""
        own.style.display = "none"
        if (!alt.parentNode) target.appendChild(alt)
    }
    const end = () => { clearTimeout(timer); show(null); target.classList.remove("ol-ta-swap-out", "ol-ta-swap-in"); resolve() }
    const swap = () => {
        target.classList.add("ol-ta-swap-out")
        timer = window.setTimeout(() => {
            step++
            show(step > words.length ? null : words[step - 1])
            target.classList.remove("ol-ta-swap-out")
            target.classList.add("ol-ta-swap-in")
            timer = window.setTimeout(() => {
                target.classList.remove("ol-ta-swap-in")
                if (step <= words.length) timer = window.setTimeout(swap, 650 / speed); else end()
            }, 300 / speed)
        }, 210 / speed)
    }
    timer = window.setTimeout(swap, 500 / speed)
    return { end, done }
}

const JS: Record<string, (root: HTMLElement, speed: number, p: any) => Job | null> = {
    scramble, counter, slot, flipclock, type: typing, rotator,
    // modui reuses these for the variants (the look differs in CSS)
    meter: counter, charge: counter, segment: counter, ticker: slot, abacus: slot, dial: slot, terminal: typing,
}

/* ---------- the component every effect shares ---------- */

function TextEffect(props) {
    const {
        anim, wrap = "", prestate = "pause",
        text = "", accent = "", words = [], charset = "mixed", chars = "",
        font, fill = "solid", color = "#111111", gradFrom = "#2DB87A", gradTo = "#4F8CFF", gradAngle = 90,
        accentColor = "#2DB87A", align = "left", split = "letter", direction = "ltr",
        trigger = "view", delay = 0, replay = "none", speed = 1, loop = false, loopDelay = 3, randomLoop = false,
        style, cssVars,
    } = props

    const ref = React.useRef<HTMLDivElement>(null)
    // on the canvas (and in static renders) the text stands still and visible; it moves in Preview and on the site
    const isCanvas = useIsStaticRenderer() || RenderTarget.current() === RenderTarget.canvas
    const content = React.useMemo(() => build(text, accent, wrap, split, direction), [text, accent, wrap, split, direction])
    const wordsKey = JSON.stringify(words)          // a list arrives as a new array on every render
    const grad = fill === "gradient"

    // gradient: every letter shows its own slice of one gradient laid over the whole text, so it holds while letters move.
    // Not on the canvas or in static renders: nothing moves there, so one gradient on the block does it (CSS, no measuring).
    // Measured at most once per frame, only when the block's size really changed, all reads before all writes.
    React.useEffect(() => {
        const root = ref.current
        if (!root || !grad || isCanvas) return
        let frame = 0, lastW = -1, lastH = -1
        const paint = () => {
            frame = 0
            const W = root.offsetWidth, H = root.offsetHeight
            if (W === lastW && H === lastH) return
            lastW = W; lastH = H
            const letters = lettersOf(root)
            const at = letters.map((o) => {
                let x = 0, y = 0, el: any = o
                while (el && el !== root) { x += el.offsetLeft; y += el.offsetTop; el = el.offsetParent }
                return [x, y]
            })
            root.style.setProperty("--gw", W + "px")
            root.style.setProperty("--gh", H + "px")
            letters.forEach((o, i) => { o.style.setProperty("--gx", at[i][0] + "px"); o.style.setProperty("--gy", at[i][1] + "px") })
        }
        const schedule = () => { if (!frame) frame = requestAnimationFrame(paint) }
        paint()
        const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(schedule) : null
        if (ro) ro.observe(root)
        return () => { cancelAnimationFrame(frame); if (ro) ro.disconnect() }
    }, [grad, content, isCanvas])

    React.useEffect(() => {
        const root = ref.current
        if (!root || isCanvas) return
        if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) return

        const run = JS[anim]
        const pace = Math.max(speed, 0.05)
        const opts = { words, charset, chars, accentColor }
        let job: Job | null = null
        let timer = 0
        let busy = false
        let stopped = false
        let observer: IntersectionObserver | null = null

        const play = () => {
            if (busy || stopped) return
            busy = true
            clearTimeout(timer)
            if (job) { job.end(); job = null }
            root.classList.remove("is-playing", "is-paused", "is-hidden")
            void root.offsetWidth                          // restart the CSS animations from the first frame
            root.classList.add("is-playing")
            job = run ? run(root, pace, opts) : null
            // the motion is over when every finite CSS animation and the JavaScript part are done
            const css = root.getAnimations
                ? root.getAnimations({ subtree: true }).filter((a) => a.effect && a.effect.getComputedTiming().iterations !== Infinity)
                : []
            Promise.all([...css.map((a) => a.finished.catch(() => {})), job ? job.done : null]).then(() => {
                busy = false
                // random: anywhere from a third to almost twice the delay, so it feels like a real fault, not a metronome
                const wait = randomLoop ? loopDelay * (0.3 + Math.random() * 1.6) : loopDelay
                if (!stopped && loop && trigger !== "hover") timer = window.setTimeout(play, wait * 1000)
            })
        }
        const begin = () => { if (delay > 0) timer = window.setTimeout(play, delay * 1000); else play() }

        if (trigger === "hover") {
            root.addEventListener("mouseenter", play)
        } else {
            // wait on the first frame (or out of sight) until it plays
            if (prestate === "pause") root.classList.add("is-playing", "is-paused")
            if (prestate === "hide") root.classList.add("is-hidden")
            if (trigger === "load" || !("IntersectionObserver" in window)) {
                begin()
            } else {
                observer = new IntersectionObserver((entries) => {
                    if (entries.some((e) => e.isIntersecting)) { observer && observer.disconnect(); begin() }
                }, { threshold: 0.3 })
                observer.observe(root)
            }
            if (replay === "hover") root.addEventListener("mouseenter", play)
            if (replay === "click") root.addEventListener("click", play)
        }

        return () => {
            stopped = true
            clearTimeout(timer)
            if (observer) observer.disconnect()
            root.removeEventListener("mouseenter", play)
            root.removeEventListener("click", play)
            if (job) job.end()
            root.classList.remove("is-playing", "is-paused", "is-hidden")
        }
    }, [anim, text, accent, wordsKey, charset, chars, accentColor, split, direction, trigger, delay, replay, speed, loop, loopDelay, randomLoop, prestate, isCanvas])

    const vars: any = {
        "--ta-speed": Math.max(speed, 0.05), "--scene-accent": accentColor, "--hl-mark": accentColor,
        "--ol-grad": "linear-gradient(" + gradAngle + "deg, " + gradFrom + ", " + gradTo + ")", ...cssVars,
    }
    return (
        <div ref={ref} className={"ol-ta" + (grad ? (isCanvas ? " is-grad-still" : " is-grad") : "")} data-anim={anim} style={{ color, textAlign: align, ...vars, ...font, ...style }}>
            <style>{BASE + CSS}</style>
            <span className="ol-sr">{text}</span>
            <span aria-hidden="true">{content}</span>
        </div>
    )
}

// the same controls on every effect, in the same order; extra ones only where the effect uses them
// more: controls only one effect has (e.g. the glitch colours), placed after the colours
function controls(d, extra: { accent?: boolean; words?: boolean; accentColor?: string; randomLoop?: boolean; order?: boolean }, more = {}) {
    const notHover = (p) => p.trigger === "hover"
    const c: any = {
        text: { type: ControlType.String, title: "Text", defaultValue: d.text, displayTextArea: true },
    }
    if (extra.accent) c.accent = { type: ControlType.String, title: "Accent word", defaultValue: d.accent }
    if (extra.words) c.words = {
        type: ControlType.Array, title: "Words", defaultValue: d.words,
        control: {
            type: ControlType.Object,
            controls: {
                word: { type: ControlType.String, title: "Word", defaultValue: "new" },
                color: { type: ControlType.Color, title: "Color", defaultValue: d.accentColor },
            },
        },
    }
    c.font = {
        type: ControlType.Font, title: "Font", controls: "extended",
        defaultFontType: "sans-serif", defaultValue: { fontSize: 64, lineHeight: "1.05em" },
    }
    c.fill = {
        type: ControlType.Enum, title: "Fill", options: ["solid", "gradient"], optionTitles: ["Solid", "Gradient"],
        displaySegmentedControl: true, defaultValue: "solid",
    }
    c.color = { type: ControlType.Color, title: "Color", defaultValue: "#111111", hidden: (p) => p.fill === "gradient" }
    c.gradFrom = { type: ControlType.Color, title: "From", defaultValue: "#2DB87A", hidden: (p) => p.fill !== "gradient" }
    c.gradTo = { type: ControlType.Color, title: "To", defaultValue: "#4F8CFF", hidden: (p) => p.fill !== "gradient" }
    c.gradAngle = { type: ControlType.Number, title: "Angle", min: 0, max: 360, step: 1, unit: "°", defaultValue: 90, hidden: (p) => p.fill !== "gradient" }
    if (extra.accentColor) c.accentColor = { type: ControlType.Color, title: extra.accentColor, defaultValue: d.accentColor }
    Object.keys(more).forEach((k) => { c[k] = { ...more[k], defaultValue: d[k] } })
    // alignment comes from the Font control (it has its own Align), so there is no second one here
    if (extra.order) {
        c.split = {
            type: ControlType.Enum, title: "Split", options: ["letter", "word", "line"],
            optionTitles: ["Letters", "Words", "Lines"], displaySegmentedControl: true, defaultValue: "letter",
        }
        c.direction = {
            type: ControlType.Enum, title: "Direction", options: ["ltr", "rtl", "center", "edges", "random"],
            optionTitles: ["Left to right", "Right to left", "From center", "From edges", "Random"], defaultValue: "ltr",
        }
    }
    c.trigger = {
        type: ControlType.Enum, title: "Trigger", options: ["view", "load", "hover"],
        optionTitles: ["In view", "On load", "On hover"], defaultValue: "view",
    }
    c.delay = { type: ControlType.Number, title: "Delay", min: 0, max: 10, step: 0.1, unit: "s", defaultValue: 0, hidden: notHover }
    c.replay = {
        type: ControlType.Enum, title: "Replay", options: ["none", "hover", "click"],
        optionTitles: ["None", "On hover", "On click"], defaultValue: "none", hidden: notHover,
    }
    c.speed = { type: ControlType.Number, title: "Speed", min: 0.1, max: 6, step: 0.01, defaultValue: 1 }
    c.loop = { type: ControlType.Boolean, title: "Loop", defaultValue: false, hidden: notHover }
    c.loopDelay = {
        type: ControlType.Number, title: "Loop delay", min: 0.5, max: 20, step: 0.5, unit: "s", defaultValue: 3,
        hidden: (p) => !p.loop || p.trigger === "hover",
    }
    if (extra.randomLoop) c.randomLoop = {
        type: ControlType.Boolean, title: "Random delay", defaultValue: true,
        description: "Repeats at uneven intervals, around the loop delay",
        hidden: (p) => !p.loop || p.trigger === "hover",
    }
    return c
}


/* Pack: every effect above in one component, picked from the Effect list */
const PackDefaults = {"effect":"rise","text":"Make it move","accent":"","accentColor":"#2DB87A","randomLoop":true,"words":[]}
const PACK = {
    rise: { wrap: "", prestate: "pause", vars: (p) => ({  }) },
    type: { wrap: "", prestate: "pause", vars: (p) => ({  }) },
    wave: { wrap: "", prestate: "pause", vars: (p) => ({  }) },
}

// the default export: a Marketplace module URL without #Name opens this one
/**
 * @framerSupportedLayoutWidth auto
 * @framerSupportedLayoutHeight auto
 */
export default function TextEffectsLite(props) {
    const p = { ...PackDefaults, ...props }
    const e = PACK[p.effect] || PACK.rise
    return <TextEffect {...p} anim={PACK[p.effect] ? p.effect : "rise"} wrap={e.wrap} prestate={e.prestate} cssVars={e.vars(p)} />
}
const packControls = (() => {
    const c = controls(PackDefaults, { accent: true, words: true, accentColor: "Accent", randomLoop: true, order: true }, {  })
    const hide = (key, test) => { const was = c[key].hidden; c[key].hidden = (p) => test(p) || (was ? was(p) : false) }
    hide("accent", (p) => ![].includes(p.effect))
    hide("words", (p) => p.effect !== "")
    hide("accentColor", (p) => !["type"].includes(p.effect))
    hide("randomLoop", (p) => ![].includes(p.effect))
    hide("split", (p) => !["rise", "wave"].includes(p.effect))
    hide("direction", (p) => !["rise", "wave"].includes(p.effect))
    return {
        effect: { type: ControlType.Enum, title: "Effect", description: "3 free effects. 40 text effects in Text Effects on the Framer Marketplace.", defaultValue: "rise",
            options: ["rise","type","wave"],
            optionTitles: ["Letter Rise","Typewriter","Wave"] },
        ...c,
    }
})()
addPropertyControls(TextEffectsLite, packControls)

